// Port of compiler/rustc_ast/src/expand/autodiff_attrs.rs
//! This crate handles the user facing autodiff macro. For each `#[autodiff(...)]` attribute,
//! we create an `RustcAutodiff` which contains the source and target function names. The source
//! is the function to which the autodiff attribute is applied, and the target is the function
//! getting generated by us (with a name given by the user as the first autodiff arg).
//
// Types and derived Debug impls are generated into autodiff_attrs.gen.ts (tools/codegen/types.ts).
// PORT: enum methods live on the companion consts (PORTING §8), re-defined here as
// `{ ...gen.X, fns }`. `FromStr` impls are `X.from_str(s): Result<X, undefined>` (`()` error).
import { sym, type Symbol } from "../../rustc_span/symbol.ts";
import { debug_int, debug_option, PLAIN } from "../../std/fmt.ts";
import { Err, Ok, type Result } from "../../std/result.ts";
import type { Ty } from "../ast.ts";
import * as gen from "./autodiff_attrs.gen.ts";

export * from "./autodiff_attrs.gen.ts";

/// Forward and Reverse Mode are well known names for automatic differentiation implementations.
/// Enzyme does support both, but with different semantics, see DiffActivity. The First variants
/// are a hack to support higher order derivatives. We need to compute first order derivatives
/// before we compute second order derivatives, otherwise we would differentiate our placeholder
/// functions. The proper solution is to recognize and resolve this DAG of autodiff invocations,
/// as it's already done in the C++ and Julia frontend of Enzyme.
export type DiffMode = gen.DiffMode;
export const DiffMode = {
  ...gen.DiffMode,

  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:36 all_modes
  all_modes(): readonly Symbol[] {
    return [sym.Source, sym.Forward, sym.Reverse];
  },

  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:104 is_rev
  is_rev(self: DiffMode): boolean {
    return self === "Reverse";
  },

  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:107 is_fwd
  is_fwd(self: DiffMode): boolean {
    return self === "Forward";
  },

  // impl FromStr for DiffMode
  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:199 from_str
  from_str(s: string): Result<DiffMode, undefined> {
    switch (s) {
      case "Error":
        return Ok(gen.DiffMode.Error);
      case "Source":
        return Ok(gen.DiffMode.Source);
      case "Forward":
        return Ok(gen.DiffMode.Forward);
      case "Reverse":
        return Ok(gen.DiffMode.Reverse);
      default:
        return Err(undefined);
    }
  },
};

/// Dual and Duplicated (and their Only variants) are getting lowered to the same Enzyme Activity.
/// However, under forward mode we overwrite the previous shadow value, while for reverse mode
/// we add to the previous shadow value. To not surprise users, we picked different names.
/// Dual numbers is also a quite well known name for forward mode AD types.
export type DiffActivity = gen.DiffActivity;
export const DiffActivity = {
  ...gen.DiffActivity,

  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:82 is_dual_or_const
  is_dual_or_const(self: DiffActivity): boolean {
    return self.$ === "Dual" || self.$ === "DualOnly" || self.$ === "Dualv" || self.$ === "DualvOnly" || self.$ === "Const";
  },

  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:87 all_activities
  all_activities(): readonly Symbol[] {
    return [
      sym.None,
      sym.Active,
      sym.ActiveOnly,
      sym.Const,
      sym.Dual,
      sym.Dualv,
      sym.DualOnly,
      sym.DualvOnly,
      sym.Duplicated,
      sym.DuplicatedOnly,
    ];
  },

  // impl FromStr for DiffActivity
  // rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:212 from_str
  from_str(s: string): Result<DiffActivity, undefined> {
    switch (s) {
      case "None":
        return Ok(gen.DiffActivity.None);
      case "Active":
        return Ok(gen.DiffActivity.Active);
      case "ActiveOnly":
        return Ok(gen.DiffActivity.ActiveOnly);
      case "Const":
        return Ok(gen.DiffActivity.Const);
      case "Dual":
        return Ok(gen.DiffActivity.Dual);
      case "Dualv":
        return Ok(gen.DiffActivity.Dualv);
      case "DualOnly":
        return Ok(gen.DiffActivity.DualOnly);
      case "DualvOnly":
        return Ok(gen.DiffActivity.DualvOnly);
      case "Duplicated":
        return Ok(gen.DiffActivity.Duplicated);
      case "DuplicatedOnly":
        return Ok(gen.DiffActivity.DuplicatedOnly);
      default:
        return Err(undefined);
    }
  },
};

// impl Display for DiffMode
// rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:113 fmt
// PORT: `Display` impls are `display_<Type>(v): string` (as in rustc_span).
export function display_DiffMode(self: DiffMode): string {
  switch (self) {
    case "Error":
      return "Error";
    case "Source":
      return "Source";
    case "Forward":
      return "Forward";
    case "Reverse":
      return "Reverse";
  }
}

/// Active(Only) is valid in reverse-mode AD for scalar float returns (f16/f32/...).
/// Dual(Only) is valid in forward-mode AD for scalar float returns (f16/f32/...).
/// Const is valid for all cases and means that we don't compute derivatives wrt. this output.
/// That usually means we have a &mut or *mut T output and compute derivatives wrt. that arg,
/// but this is too complex to verify here. Also it's just a logic error if users get this wrong.
// rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:128 valid_ret_activity
export function valid_ret_activity(mode: DiffMode, activity: DiffActivity): boolean {
  if (activity.$ === "None") {
    // Only valid if primal returns (), but we can't check that here.
    return true;
  }
  switch (mode) {
    case "Error":
      return false;
    case "Source":
      return false;
    case "Forward":
      return DiffActivity.is_dual_or_const(activity);
    case "Reverse":
      return activity.$ === "Const" || activity.$ === "Active" || activity.$ === "ActiveOnly";
  }
}

/// For indirections (ptr/ref) we can't use Active, since Active allocates a shadow value
/// for the given argument, but we generally can't know the size of such a type.
/// For scalar types (f16/f32/f64/f128) we can use Active and we can't use Duplicated,
/// since Duplicated expects a mutable ref/ptr and we would thus end up with a shadow value
/// who is an indirect type, which doesn't match the primal scalar type. We can't prevent
/// users here from marking scalars as Duplicated, due to type aliases.
// rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:151 valid_ty_for_activity
export function valid_ty_for_activity(ty: Ty, activity: DiffActivity): boolean {
  // It's always allowed to mark something as Const, since we won't compute derivatives wrt. it.
  // Dual variants also support all types.
  if (DiffActivity.is_dual_or_const(activity)) {
    return true;
  }
  // FIXME(ZuseZ4) We should make this more robust to also
  // handle type aliases. Once that is done, we can be more restrictive here.
  if (activity.$ === "Active" || activity.$ === "ActiveOnly") {
    return true;
  }
  return (ty.kind.$ === "Ptr" || ty.kind.$ === "Ref") && (activity.$ === "Duplicated" || activity.$ === "DuplicatedOnly");
}

// rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:166 valid_input_activity
export function valid_input_activity(mode: DiffMode, activity: DiffActivity): boolean {
  switch (mode) {
    case "Error":
      return false;
    case "Source":
      return false;
    case "Forward":
      return DiffActivity.is_dual_or_const(activity);
    case "Reverse":
      return (
        activity.$ === "Active" ||
        activity.$ === "ActiveOnly" ||
        activity.$ === "Duplicated" ||
        activity.$ === "DuplicatedOnly" ||
        activity.$ === "Const"
      );
  }
}

// impl Display for DiffActivity
// rustc: compiler/rustc_ast/src/expand/autodiff_attrs.rs:179 fmt
export function display_DiffActivity(self: DiffActivity): string {
  switch (self.$) {
    case "None":
      return "None";
    case "Const":
      return "Const";
    case "Active":
      return "Active";
    case "ActiveOnly":
      return "ActiveOnly";
    case "Dual":
      return "Dual";
    case "Dualv":
      return "Dualv";
    case "DualOnly":
      return "DualOnly";
    case "DualvOnly":
      return "DualvOnly";
    case "Duplicated":
      return "Duplicated";
    case "DuplicatedOnly":
      return "DuplicatedOnly";
    case "FakeActivitySize":
      // PORT: `write!(f, "..{:?}..", s)` formats `s` with a fresh formatter (`PLAIN`).
      return `FakeActivitySize(${debug_option(self._0, PLAIN, debug_int)})`;
  }
}
